import os
import requests
import json

def extract_invoice_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Missing OpenAI API key. Set OPENAI_API_KEY or pass config['api_key'].")

    model = config.get("model", "gpt-4.1-mini")
    endpoint = config.get("endpoint", "https://api.openai.com/v1/responses")

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    prompt = (
        "Extract structured invoice data from the provided document payload. "
        "Return ONLY valid JSON with exactly these top-level keys: vendor, date, total, line_items. "
        "vendor should be a string or null. date should be an ISO-8601 date string or null. "
        "total should be a number or null. line_items should be an array of objects, each with "
        "description, quantity, unit_price, amount. Use null when a value is unavailable."
    )

    input_content = [
        {
            "role": "system",
            "content": prompt,
        },
        {
            "role": "user",
            "content": [
                {
                    "type": "text",
                    "text": "Extract invoice fields from this payload:",
                },
                {
                    "type": "text",
                    "text": json.dumps(payload) if not isinstance(payload, str) else payload,
                },
            ],
        },
    ]

    request_body = {
        "model": model,
        "input": input_content,
        "temperature": 0,
    }

    response = requests.post(endpoint, headers=headers, json=request_body, timeout=config.get("timeout", 60))
    response.raise_for_status()
    result = response.json()
    return result
